$(document).on("change keyup input click", "[data-phone-mask]", function (e) {
  var curVal = $(e.currentTarget).val();
  if (curVal.match(/[^0-9]/g)) {
    $(e.currentTarget).val(function (index, value) {
      return value.replace(/[^0-9]/g, "");
    });
  }
});

