$(window).scroll(() => {
  let wsup = $(window).scrollTop() - $("body").position().top;
  if (wsup > 900) {
    $(".up").animate({ opacity: 1 }, 0);
  } else {
    $(".up").animate({ opacity: 0 }, 0);
  }
});
$(".up").click(() => {
  $("html, body").animate({ scrollTop: $("body").offset().top }, 500);
});

